function fresh(){return {version:1,started:false,name:'Vô Danh',classId:0,level:1,xp:0,gold:200,potions:5,kills:0,bossKills:0,quest:0,zone:0,x:940,y:850,hp:180,mp:100,items:[{id:1,slot:0,rarity:0,level:1,enhance:0}],equipped:[1,null,null],lastSave:Date.now(),settings:{sound:false,particles:true},daily:''};}
