  state.name=String(state.name||'Vô Danh').slice(0,18);
  state.items=state.items.filter(i=>i&&Number.isFinite(i.id)&&i.slot>=0&&i.slot<=2&&i.rarity>=0&&i.rarity<=3).map(i=>({...i,level:Math.max(1,Math.min(100,i.level|0)),enhance:Math.max(0,Math.min(20,i.enhance|0))}));
