function itemValue(i){return Math.round((i.slot===0?5:i.slot===1?4:3)*(1+i.rarity*.85)*(1+(i.level-1)*.18)*(1+i.enhance*.15));}
function stats(){let attack=CLASSES[state.classId].atk+(state.level-1)*4,defense=3+(state.level-1)*1.5,maxHp=CLASSES[state.classId].hp+(state.level-1)*28;state.equipped.forEach(id=>{let i=state.items.find(t=>t.id===id);if(!i)return;const v=itemValue(i);if(i.slot===0)attack+=v;else if(i.slot===1){defense+=v;maxHp+=v*4;}else{attack+=v;maxHp+=v*3;}});return{attack:Math.round(attack),defense:Math.round(defense),maxHp,mp:100+(state.level-1)*6,power:Math.round(attack*5+defense*3+maxHp*.4)};}
