  [[590,610],[1320,640],[1170,1180],[560,1070],[1480,1000],[650,270],[1220,300]].forEach((p,i)=>decor.push({kind:i%3===0?'cherry':'tree',x:p[0],y:p[1],scale:1.05,seed:155+i}));
  for(let i=0;i<45;i++){let x=60+rng()*(W-120),y=180+rng()*(H-240);if(clear(x,y)||(x<500&&y<1250))continue;decor.push({kind:'rock',x,y,scale:.4+rng()*.7,seed:i});}
  [[760,630],[1100,630],[820,960],[1100,1010],[1350,380]].forEach(p=>decor.push({kind:'lantern',x:p[0],y:p[1],scale:1}));
  for(let i=0;i<80;i++){let x=rng()*W,y=rng()*H;if(clear(x,y)||(x<500&&y<1250))continue;for(let j=0;j<3;j++){line(c,x+j*4,y,x+j*5-2,y-6-rng()*7,z.grass[2],1);}}
